function [Ksr,Ksc,Ksv,Jsr,Jsc,Jsv,Fsr,Fsv,fc,kc,jc] = AssembleSparseLaplace_FR(iele,nnpe,np,numind,eqv,se,me,fe,Ksr,Ksc,Ksv,Jsr,Jsc,Jsv,Fsr,Fsv,fc,kc,jc)% % Called by Ormonics% % assembles elemental force mass and stiffness matrices into global counterparts% assuming sparse matrices% Solution is for a scalar field    for  i=1:1:nnpe              ii = np(iele,i);         if(ii>numind)        ieqv = ii - numind;        ii = eqv(2,ieqv);%         message = ['Replacing ' num2str(np(iele,i)) ' with ' num2str(ii) ];%         disp(message)        end          Fsr(fc)=ii;         Fsv(fc)=fe(i);         fc=fc+1;                    for j=1:1:nnpe                        jj=np(iele,j);	               if(jj>numind)               jeqv = jj - numind;               jj = eqv(2,jeqv);%                message = ['Replacing ' num2str(np(iele,j)) ' with ' num2str(jj) ];%                disp(message)               end                        Ksr(kc)=ii;             Ksc(kc)=jj;             Ksv(kc)=se(i,j);             kc=kc+1;            Jsr(jc)=ii;             Jsc(jc)=jj;             Jsv(jc)=me(i,j);             jc=jc+1;                   end    end